def solve(n):
    """Return count of prime numbers strictly less than *n*.
    Uses an efficient Sieve of Eratosthenes implementation that avoids
    slice assignments when the start index exceeds the sieve range.
    """
    if n <= 2:
        return 0
    limit = n - 1
    sieve = bytearray(b'\x01') * (limit + 1)
    sieve[0:2] = b'\x00\x00'
    import math
    max_factor = int(math.isqrt(limit))
    for p in range(2, max_factor + 1):
        if sieve[p]:
            start = p * p
            if start > limit:
                continue
            step = p
            sieve[start:limit + 1:step] = b'\x00' * ((limit - start) // step + 1)
    return sum(sieve)

