def solve(n):
    """Return the number of prime numbers strictly less than n.
    Simple Sieve of Eratosthenes.
    """
    if n <= 2:
        return 0
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    import math
    for p in range(2, int(math.isqrt(n - 1)) + 1):
        if sieve[p]:
            step = p
            start = p * p
            for multiple in range(start, n, step):
                sieve[multiple] = False
    return sum(sieve)

