def solve(meetings):
    """Return the maximum number of non-overlapping meetings.
    Handles meetings where start may be greater than end by swapping.
    Uses greedy algorithm sorting by end time then start.
    """
    # Normalize meetings: ensure each is a tuple (start, end) with start <= end
    normalized = []
    for m in meetings:
        try:
            s, e = m
        except Exception:
            continue
        if not isinstance(s, (int, float)) or not isinstance(e, (int, float)):
            continue
        if s > e:
            s, e = e, s
        normalized.append((s, e))
    # Sort by end time, then by start for deterministic tie-breaking
    normalized.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in normalized:
        if s >= last_end:
            count += 1
            last_end = e
    return count

