def solve(matrix):
    # determinant of a square matrix. Empty matrix -> 1.
    n = len(matrix)
    if n == 0:
        return 1
    if n == 1:
        return matrix[0][0]
    # Use Laplace expansion recursively (could be O(n!)) but n likely small in tests.
    def det(mat):
