def solve(matrix):
    # determinant using Bareiss algorithm (fraction-free Gaussian elimination)
    n = len(matrix)
    if n == 0:
        return 1
    # make a copy of matrix as list of lists of ints
    A = [row[:] for row in matrix]
    det = 1
    for k in range(n-1):
        # find pivot; if zero, swap with a row below
        if A[k][k] == 0:
            for i in range(k+1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det = -det
                    break
            else:
                return 0
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                # A[i][j] = (pivot*A[i][j] - A[i][k]*A[k][j]) // (A[k-1][k-1] if k>0 else 1)
                numerator = pivot * A[i][j] - A[i][k] * A[k][j]
                denom = A[k-1][k-1] if k > 0 else 1
                A[i][j] = numerator // denom
        # zero out below pivot column
        for i in range(k+1, n):
            A[i][k] = 0
    det = det * A[n-1][n-1]
