def solve(matrix):
    """Return the determinant of a square integer matrix.
    Empty matrix has determinant 1.
    Uses the Bareiss fraction‑free Gaussian elimination algorithm for
    exact integer arithmetic.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Make a mutable copy
    A = [row[:] for row in matrix]
    det_sign = 1
    for k in range(n - 1):
        # Pivot handling: if zero, swap with a lower row
        if A[k][k] == 0:
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    A[k], A[i] = A[i], A[k]
                    det_sign = -det_sign
                    break
            else:
                return 0
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                # Bareiss update (exact division)
                A[i][j] = (pivot * A[i][j] - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
    return det_sign * A[-1][-1]

