def solve(coins, amount):
    if amount == 0:
        return 0
    if not coins or amount < 0:
        return -1
    usable = sorted({c for c in coins if isinstance(c, int) and c > 0})
    if not usable or usable[0] > amount:
        return -1
    INF = float('inf')
    dp = [0] + [INF] * amount
    for a in range(1, amount + 1):
        for c in usable:
            if c > a:
                break
            if dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

